// Keep unsaved form drafts across state refreshes, scoped to account/project/panel.
const tramDrafts=new Map();window.tramDrafts=tramDrafts;let renderedDraftKey=null;
function captureDraft(){if(!renderedDraftKey)return;const values={};$('#drawerBody').querySelectorAll('input,textarea,select').forEach((field,i)=>{if(['password','file'].includes(field.type))return;const key=field.id||field.name||'field-'+i;values[key]={value:field.value,checked:field.checked,type:field.type}});tramDrafts.set(renderedDraftKey,values)}
const panelBeforePolish=renderPanel;
renderPanel=function(view){captureDraft();const key=(typeof signedIn!=='undefined'?signedIn?.id:'visitor')+':'+project().id+':'+view;const result=panelBeforePolish(view);renderedDraftKey=key;const restore=()=>{if(renderedDraftKey!==key)return;const saved=tramDrafts.get(key);if(!saved)return;$('#drawerBody').querySelectorAll('input,textarea,select').forEach((field,i)=>{if(['password','file'].includes(field.type))return;const value=saved[field.id||field.name||'field-'+i];if(!value)return;if(field.type==='checkbox')field.checked=value.checked;else field.value=value.value})};restore();if(result?.then)result.then(restore);return result};
const closeBeforePolish=closePanel;closePanel=function(){captureDraft();return closeBeforePolish()};
let projectAtRender=project().id;
const renderBeforePolish=render;
render=function(){const old=projectAtRender;renderBeforePolish();projectAtRender=project().id;if(old!==projectAtRender){clearTimeout(realPoll);realPoll=null;realJob=null;if(window.tramRestoreJobs)window.tramRestoreJobs()}showRealActivity()};
function showRealActivity(){if(!realJob||realJob.projectId!==project().id)return;const index=staff.findIndex(a=>a.id===realJob.roleId);if(index<0)return;const node=$(`[data-actor="${index}"]`);if(['running','queued'].includes(realJob.state)){node?.classList.add('busy');$('#liveNote').innerHTML=`<b>${escapeHTML(staff[index].name)} · Codex thật</b>Đang ${escapeHTML(realJob.type==='build'?'tạo sản phẩm và kiểm tra':realJob.type==='suggest'?'đề xuất ý tưởng':'xử lý yêu cầu')}. Theo dõi trong AI thật.`;$('#missionTitle').textContent='Tác vụ Codex thực tế';$('#missionStatus').textContent='Đang chạy · Không phải mô phỏng';}else if(realJob.state==='completed'){node?.classList.remove('busy');node?.classList.add('done');$('#liveNote').innerHTML='<b>Đã có kết quả Codex thật</b>Mở AI thật để xem đầu ra và các file đã tạo.';}}
const originalPollRealJob=pollRealJob;let pollFailures=0;
pollRealJob=async function(){clearTimeout(realPoll);if(!realJob||!['queued','running'].includes(realJob.state))return;try{const before=realJob.state;realJob=await localCall('/jobs/'+encodeURIComponent(realJob.id));pollFailures=0;if(['completed','failed','interrupted'].includes(realJob.state)){workbenchStatus=realJob.state==='completed'?'Đã có đầu ra thật. Kiểm tra file và bằng chứng trước khi sử dụng.':realJob.error;if(before!=='completed'&&realJob.state==='completed'){const idx=staff.findIndex(a=>a.id===realJob.roleId);const next=order[order.indexOf(idx)+1]??0;if(window.TramWalking)window.TramWalking.handoff(realJob.roleId,staff[next].id)}}else workbenchStatus='Codex đang làm việc thật. Bạn có thể chuyển mục khác trong Trạm.';showRealActivity();if(drawerView==='workbench')renderPanel('workbench');if(['queued','running'].includes(realJob.state))realPoll=setTimeout(pollRealJob,2500)}catch(e){pollFailures++;workbenchStatus='Tạm mất kết nối. Đang thử lại; không gửi việc trùng. '+e.message;if(drawerView==='workbench')renderPanel('workbench');if(pollFailures<8)realPoll=setTimeout(pollRealJob,Math.min(2000*pollFailures,15000));else workbenchStatus='Cần kiểm tra máy chủ. Mở lại AI thật để khôi phục theo dõi tác vụ.'}};
const benchOriginal=panelExtensions.workbench;let restoringJobs=false,benchSubmitting=false;
panelExtensions.workbench=function(){benchOriginal();const form=$('#realIdeaForm');if(form){const submit=form.onsubmit;form.onsubmit=async e=>{e.preventDefault();if(benchSubmitting)return;benchSubmitting=true;const button=form.querySelector('button');button.disabled=true;try{await submit(e)}finally{benchSubmitting=false;if(button.isConnected)button.disabled=false;showRealActivity()}}}const input=$('#attachments');if(input){const upload=input.onchange;input.onchange=async e=>{if(workbenchBusy)return;input.disabled=true;try{await upload(e)}finally{if(input.isConnected)input.disabled=false}}}if(!realJob&&signedIn&&!restoringJobs&&window.tramRestoreJobs){restoringJobs=true;window.tramRestoreJobs().finally(()=>{restoringJobs=false})}};
$('#welcome').addEventListener('close',()=>sessionStorage.setItem('tram-intro-v2','seen'));if(sessionStorage.getItem('tram-intro-v2'))$('#welcome').close();
const baseActorState=actorState;actorState=function(index){const value=baseActorState(index);return value==='busy'&&!timer?'assigned':value};
window.addEventListener('beforeunload',e=>{if(typeof pendingSnapshots!=='undefined'&&pendingSnapshots.size){e.preventDefault();e.returnValue=''}});
